edits.find:
if (Math.hypot(p.x - pl.x, p.y + 0.4 - gy, p.z - pl.z) < 0.95) {
  pl.g.remove(pl.gem); pl.gem = null; gems++;
  logEvent("gem", { platform: pl.id, total: gems, height: pl.gem.position.y });
  sfx.gem(); burst(pl.x, gy - 0.1, pl.z, 10, 0.9);
}

edits.replace:
if (Math.hypot(p.x - pl.x, p.y + 0.4 - gy, p.z - pl.z) < 0.95) {
  const gemH = pl.gem.position.y;
  pl.g.remove(pl.gem); pl.gem = null; gems++;
  logEvent("gem", { platform: pl.id, total: gems, height: gemH });
  sfx.gem(); burst(pl.x, gy - 0.1, pl.z, 10, 0.9);
}

edits.find:
const h = Math.floor(maxY);
if (h !== shownH) { shownH = h; hHeight.textContent = h; }
hGems.textContent = gems;
hBest.textContent = best;

edits.replace:
const h = Math.floor(maxY);
if (h !== shownH) { shownH = h; hHeight.textContent = h; }
hGems.textContent = gems;
hBest.textContent = Math.max(best, h);
